INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmowxqr8v000w2sqos2p2ug2b','cmowxqo7o00022sqo171jv27b','Boundaries Are Love','Saying no makes your yes meaningful.','Where do you need a clearer boundary?',NULL,NULL,'FREE',0,1,2,'2026-05-08 13:12:59.503','2026-05-14 12:14:28.242');
