INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmowxqre7000y2sqoqq0afjid','cmowxqo7o00022sqo171jv27b','Be Witnessed','Let yourself be seen.','Who sees you clearly? How does it feel?',NULL,NULL,'PREMIUM',0,1,4,'2026-05-08 13:12:59.695','2026-05-14 12:14:28.529');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxe9x00016sqoi1a277iv','cmp2sxe5v00006sqo1dppvi36','Planetary Influence','The energies of celestial bodies surround us at all times. By making the choice to work with these planetary influences, we empower ourselves to navigate our personal journeys with greater harmony and purpose. Each major celestial body offers unique forms of energetic guidance — from the Sun\'s insight into your identity, to the Moon\'s influence on emotions, to Saturn\'s encouragement of focus. Visualize having a one-to-one with a cosmic friend when asking for assistance, not a distant rock in the sky.','Which celestial body\'s energy are you most drawn to right now, and why?','/cards/01-planetary-influence.png',NULL,'FREE',1,1,1,'2026-05-12 15:44:48.261','2026-05-14 12:14:28.805');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxeck00026sqopg9vno0d','cmp2sxe5v00006sqo1dppvi36','Telescope','Sometimes we simply don\'t have all the answers, and we must trust that the Source has placed something in our path for a reason. If we don\'t understand the situation, it\'s perfectly fine to send it back and ask for clarification. Picture your problem floating through the porthole in the center of the Telescope toward the light of Source to be cleansed of confusion and returned reconfigured for better understanding. Source truly appreciates when you ask and connect, and the answers you need will always find their way to you.','What in your life needs to be sent to the light for clarity right now?','/cards/02-telescope.png',NULL,'FREE',1,1,2,'2026-05-12 15:44:48.356','2026-05-14 12:14:28.943');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxef800036sqoyi2qhsrz','cmp2sxe5v00006sqo1dppvi36','Humor','Humor is the key of lightening up. When on the path of spiritual development, we can forget that laughing at ourselves is a necessary part of the larger act. In this world play, it\'s okay to crack up on stage and have the audience laugh with you — in fact, it\'s required from time to time. Spirituality is a serious thing; a good chuckle at the human condition is part of the process of equilibrium.','What heavy load could you lighten with a moment of genuine self-compassion and humor?','/cards/03-humor.png',NULL,'FREE',0,1,3,'2026-05-12 15:44:48.452','2026-05-14 12:14:29.099');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxehz00046sqo1mrtwxgq','cmp2sxe5v00006sqo1dppvi36','Window Pane','Window Pane is the key of revealing the soul — the portal through which your inner truth steps into the outer world. It takes courage to let your true self be witnessed without filters or masks, but in doing so you honor your connection to Source. When you allow your soul to shine outward through your eyes, you invite others to recognize their own light by reflecting back to them their truths. You become a beacon showing that authenticity is strength and vulnerability is power.','What part of your true self have you been hiding that is ready to be seen?','/cards/04-window-pane.png',NULL,'FREE',0,1,4,'2026-05-12 15:44:48.551','2026-05-14 12:14:29.241');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxel600056sqoh3wh6apm','cmp2sxe5v00006sqo1dppvi36','Halo','Opening your mind means loosening your grip on what you think you already understand — the willingness to release rigid ideas and let fresh inspiration flow in. When you allow new thoughts to move through you rather than fixating on them, this is the beginning of true mental expansion. Give yourself permission to explore the things you\'ve always been interested in, without fear of judgment or ridicule. Curiosity is a doorway for growth, and every new experience brings you closer to the fullest version of yourself.','What idea or curiosity have you been too afraid to explore?','/cards/05-halo.png',NULL,'FREE',0,1,5,'2026-05-12 15:44:48.666','2026-05-14 12:14:29.389');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxenw00066sqo05cqwwuv','cmp2sxe5v00006sqo1dppvi36','Readiness','You are entering a new way of walking in the world — one empowered by your deep connection to both the Father God and the Mother Goddess. The Father offers clarity, prosperity, and protection; the Mother offers nurturing, intuition, and support. This is your moment of rebirth, and the identities you once carried belonged to an outdated version of you. Move forward with open arms: with this divine balance as your foundation, you are ready, unshaken, unapologetic, and fully aligned to rise into who you were always meant to be.','In what area of your life do you feel ready to step into a new version of yourself?','/cards/06-readiness.png',NULL,'FREE',1,1,6,'2026-05-12 15:44:48.764','2026-05-14 12:14:29.534');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxeqn00076sqo5mhls4ha','cmp2sxe5v00006sqo1dppvi36','Quilt','In times of difficulty, the image of a Quilt provides a sense of relief and reassurance. The protective Quilt serves as energetic insulation — like the generous, all-encompassing hug of The Great Mother. Your Guardian Angel is watching over you with unconditional love and fierce compassion; you are never truly alone. The entire Universe, including loved ones who have passed on, surrounds you with protection and guidance at all times.','Where do you need to ask for support and let yourself truly be held?','/cards/07-quilt.png',NULL,'FREE',0,1,7,'2026-05-12 15:44:48.863','2026-05-14 12:14:29.679');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxetg00086sqoa1kdgx2c','cmp2sxe5v00006sqo1dppvi36','Concentration','Concentration becomes difficult when you\'re stressed or overwhelmed, making even simple tasks feel impossible because your mind can\'t maintain its natural, fluid rhythm. This is the moment to pause, breathe, and come back to center. Focus on the center of this image and notice what your perception does — are you moving through it, or is it moving toward you? Relax and let the visual flow, mirroring the natural undulation of your body\'s electrical impulses, and allow your focus to steady and restore.','What is pulling your focus right now — toward something, or away from it?','/cards/08-concentration.png',NULL,'FREE',0,1,8,'2026-05-12 15:44:48.964','2026-05-14 12:14:29.825');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxew600096sqozwott9y2','cmp2sxe5v00006sqo1dppvi36','Arachnid','Arachnid is the key of recognizing emotional trauma patterns — echoes of generations of emotional imprints, beliefs, and survival mechanisms passed from one lineage to the next. Like a spider weaving its web, we create intricate patterns in our lives, often without realizing we are repeating the same design. Awareness is the first step to liberation; once you can see the pattern\'s origin clearly, you gain the power to transform it. In that moment, you shift from being caught in the web to becoming the conscious weaver of your own reality.','What emotional pattern have you noticed repeating in your life?','/cards/09-arachnid.png',NULL,'FREE',0,1,9,'2026-05-12 15:44:49.062','2026-05-14 12:14:29.967');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxeyy000a6sqohimwvpo3','cmp2sxe5v00006sqo1dppvi36','Surrender Flag','This is a key of humbly backing down. When faced with unpredictable outcomes, it is important to metaphorically raise your white flag and surrender to whatever the situation may bring, enabling assistance to flow through rather than meeting resistance. Letting go of the desire to control an outcome requires true bravery. Trust that the divine can see in all directions and far into the future, and believe that everything will fall into perfect order.','What are you gripping tightly that might be better surrendered to something greater?','/cards/10-surrender-flag.png',NULL,'FREE',0,1,10,'2026-05-12 15:44:49.162','2026-05-14 12:14:30.110');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxf1x000b6sqo0sqjlx7w','cmp2sxe5v00006sqo1dppvi36','Neatness','Neatness is the art of aligning your goals, dreams, and wishes so they form a clear, unified path toward your higher living. In a world shaped by thought energy, scattered intentions create scattered results in the physical realm. Neatness invites you to bring your inner world into harmony, lining up your aspirations so they support each other rather than compete. By keeping your inner priorities clear and tidy, you create a powerful energetic stream that naturally carries you forward toward your intended reality.','What one intention, if clarified, would bring the most harmony to your life right now?','/cards/11-neatness.png',NULL,'FREE',0,1,11,'2026-05-12 15:44:49.269','2026-05-14 12:14:30.255');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxf4p000c6sqoxjk842f3','cmp2sxe5v00006sqo1dppvi36','Nightwing','Nightwing is the key of inner navigation through darkness — a symbol that teaches you to ground and center yourself during times of challenge or crisis. Like a bat that uses sonar to fly through the night, you too have a deep inner sensing that can guide you safely when nothing around you seems clear. In moments of fear or overwhelm, fly inward instead of away — retreat into your inner cave where the Divine Mother awaits your arrival, where darkness is your ally. Close your eyes, breathe deeply, and listen not for sound, but for the silence beneath it.','What truth is waiting in the silence that you have been avoiding?','/cards/12-nightwing.png',NULL,'FREE',0,1,12,'2026-05-12 15:44:49.369','2026-05-14 12:14:30.416');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxf7f000d6sqoegkfzb9y','cmp2sxe5v00006sqo1dppvi36','Gods Eye','There are moments when the Divine falls completely silent, and these periods can be deeply unsettling — triggering old fears of abandonment and betrayal. But this silence isn\'t punishment; it\'s a test of your inner mettle. What feels like spiritual withdrawal is often the moment when your inner strength is being activated. Trust is what carries you across the empty spaces where certainty used to live; you are not actually alone, simply being given room to step into your own capacity.','Where in your life are you being called to trust without waiting for external confirmation?','/cards/13-gods-eye.png',NULL,'FREE',1,1,13,'2026-05-12 15:44:49.467','2026-05-14 12:14:30.553');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxfa6000e6sqoz21yji0f','cmp2sxe5v00006sqo1dppvi36','Elevator','Elevator is a key of perspective — understanding that achieving true clarity sometimes requires stepping beyond the limitations of physical existence. By temporarily releasing your consciousness from your earthly presence through meditation, you can access insights otherwise out of reach. Allow your spirit to gently rise and observe your physical form from a distance, remembering that you are a spiritual being having a human experience. Ask why a spiritual being like you is needed here on Earth at this time, and invite your guides to reveal your soul\'s mission.','From a higher perspective, what is your soul\'s purpose in your current situation?','/cards/14-elevator.png',NULL,'FREE',0,1,14,'2026-05-12 15:44:49.566','2026-05-14 12:14:30.690');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxfd5000f6sqoptsk7p4t','cmp2sxe5v00006sqo1dppvi36','Three Phases of the Moon','Honoring the energy of the lunar phases — new, quarters, and full — involves consciously adapting to the moon\'s changing cycles. The New Moon is a time of pure potential and new beginnings; the Waxing Moon calls for forward action; the Full Moon marks celebration and fulfillment; and the Waning Moon invites release and letting go. By intentionally aligning with these rhythms rather than resisting them, we foster harmony, balance, and greater control over our daily lives. Try incorporating these cycles into your life and see if going with the flow serves you better than fighting against it.','What phase of the lunar cycle mirrors where you are in your life right now?','/cards/15-three-phases-of-the-moon.png',NULL,'FREE',0,1,15,'2026-05-12 15:44:49.673','2026-05-14 12:14:30.831');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxfgj000g6sqoj1ehooch','cmp2sxe5v00006sqo1dppvi36','Bear Hug','The Bear Hug key lightens a heavy load. When we are deep in healing and no person is available to hold us, the Universe gives hugs too — picture it extending its energetic arms, inviting you in, and letting you fall all in, knowing it is safe. Your past loved ones and pets are also accessible; you do not need to label yourself a medium to feel their presence, as they are right there supporting you the whole way. Fear is the only thing holding you back from connecting freely, so don\'t go without — ask for that Bear Hug.','What connection — seen or unseen — could you lean into for support today?','/cards/16-bear-hug.png',NULL,'FREE',0,1,16,'2026-05-12 15:44:49.795','2026-05-14 12:14:30.970');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxfje000h6sqoh0u40jit','cmp2sxe5v00006sqo1dppvi36','Doorway','Entering Goddess is a key that signifies an invitation into a realm governed by symbols — she invites you to learn her language, but you must be very quiet and still to do so. By accepting this invitation, you gain extra guidance that aids in your ongoing development, offering a glimpse of what\'s going on around you by looking at the symbolic world that interplays within the physical one. Noticing messages within number sequences, music lyrics, animal totems, plants, movies, clouds, and dreams opens you to her wealth of information. She is waiting to help if you are willing to look, listen, and believe.','What symbol or sign from the universe have you been noticing lately?','/cards/17-doorway.png',NULL,'FREE',0,1,17,'2026-05-12 15:44:49.898','2026-05-14 12:14:31.111');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxfmh000i6sqojykallta','cmp2sxe5v00006sqo1dppvi36','Church Steeple','The Inner Compass functions as a sensitive receiver that corresponds to the chakras in the palms of your hands, enabling you to sense imbalances and channel healing energy. When long-standing health issues aren\'t fully recognized as frequencies, their effects can persist in the body for years. This doesn\'t mean you should delay or avoid seeing your doctor — professional care is essential. But you can also support your own healing by beginning the journey of understanding how your mind, body, emotions, and energy work together to create disease, or dissolve it.','What area of your body or life is asking for healing attention right now?','/cards/18-church-steeple.png',NULL,'FREE',0,1,18,'2026-05-12 15:44:50.009','2026-05-14 12:14:31.251');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxfqg000j6sqod5txvjgp','cmp2sxe5v00006sqo1dppvi36','Caution','In unstable situations, impulsive action can threaten both your inner peace and your physical safety, which is why blending spiritual wisdom with practical knowledge is crucial. Your inner wisdom understands when silence offers more safety than confrontation, and when thoughtful planning is wiser than immediate reaction. From a spiritual perspective, boundary-setting becomes an act of sacred self-preservation — protecting your inner light and outer body from harm. By honoring both spiritual guidance and real-world caution, you protect your well-being and build healthy boundaries that guide you toward freedom with strength and grace.','Where do you need to move with more care and intention before acting?','/cards/19-caution.png',NULL,'FREE',0,1,19,'2026-05-12 15:44:50.152','2026-05-14 12:14:31.394');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxftg000k6sqob04y7fz7','cmp2sxe5v00006sqo1dppvi36','Stop Sign','There are times when you feel overwhelmed and need both time and space. Creating this distance is crucial, as it allows you to regroup and recharge — sometimes you need everything to simply stop, granting you a moment to collect your thoughts and regain your composure. Allow yourself this moment to release the demands of the outside world and return to the sanctuary within. Honor the wisdom that led you here, forgive yourself for not pausing sooner, and let yourself become attuned once again to what feeds you, not what drains you.','What do you need to pause, decline, or set aside to restore your well-being?','/cards/20-stop.png',NULL,'FREE',0,1,20,'2026-05-12 15:44:50.260','2026-05-14 12:14:31.535');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxfwm000l6sqoeqvwf2is','cmp2sxe5v00006sqo1dppvi36','Stairway','Stairway invites you to rise above your situation to get a clear view of what\'s really happening. When we face a challenge that needs a clear perspective, the best way to understand it is to get far away from it and then return with a fresher approach. Ascension — whether of your soul, thoughts, or emotions — clears you from staying stuck in repetitive patterns; you can only solve a problem if you step back and away from it. Like the Phoenix rising from its own ashes, it may be time for you to rise anew, leaving behind the past and embracing a fresh start.','What challenge would look entirely different if you viewed it from a much higher perspective?','/cards/21-stairway.png',NULL,'FREE',0,1,21,'2026-05-12 15:44:50.374','2026-05-14 12:14:31.674');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxfzq000m6sqo595124vq','cmp2sxe5v00006sqo1dppvi36','Third Eye','Third Eye is the key of intuition — the inner lens that perceives what lies beneath the surface of any issue. To open the Third Eye, the mind and body must be grounded and still enough to receive its subtle visions and impressions. When an opening occurs, your inner vision expands dramatically, and you can see or sense everything around you and within your field. With regular practice, this intuitive gateway becomes clearer and more responsive — a powerful portal to wisdom not yet consciously known.','What does your intuition know that your rational mind is not yet accepting?','/cards/22-third-eye.png',NULL,'FREE',0,1,22,'2026-05-12 15:44:50.486','2026-05-14 12:14:31.816');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxg31000n6sqoqe7w18c6','cmp2sxe5v00006sqo1dppvi36','Male','The Male key is to allow the Feminine into your physical spaces. To truly embody the feminine, recognize her within your psyche and display her presence outwardly — through small tokens, charms, an altar, or weaving her influence into daily routines like cooking organic foods, gardening, or creating with natural elements. While masculine representations are abundant, consciously making the invisible feminine energy visible is a profound act of respect. Balance of the masculine and feminine is key — healing yourself begins in your inner world, and healing the greater world begins within the walls of your own home.','How can you invite more feminine energy — nurturing, nature, creativity — into your daily life?','/cards/23-male.png',NULL,'FREE',0,1,23,'2026-05-12 15:44:50.605','2026-05-14 12:14:31.955');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxg61000o6sqoxqf2sest','cmp2sxe5v00006sqo1dppvi36','Ceiling','Ceiling teaches us that ascension and descension are two sides of the same spiritual coin. Living only in the light creates a spiritual addiction to bliss while ignoring the shadow aspects quietly waiting for illumination — like Icarus, flying too close to the sun will cause a fall. Yet living mostly in the dark pulls you into heaviness, convincing you that you are unloved and unworthy. The soul\'s true work is to find the center: recognize your extremes, seek what lies between them, and dissolve the patterns at their root so they quietly fall away from your energetic field.','Where are you staying too high or too low? What would true center feel like?','/cards/24-ceiling.png',NULL,'FREE',0,1,24,'2026-05-12 15:44:50.713','2026-05-14 12:14:32.094');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxg8p000p6sqov6h9ouds','cmp2sxe5v00006sqo1dppvi36','Hourglass','Hourglass is the key of divine timing — the reminder that every moment has its proper place in the unfoldment of your life. Even when you already know the answer, there are times when waiting is the wisest action; at other moments, you are called to leap forward even before you feel fully ready. We are not meant to see the whole picture all at once — we are on a need-to-know basis, and demanding the final outcome can sabotage the very thing we\'re trying to create. Trust that everything is unfolding for your highest good, and that each perfectly timed step will benefit you in ways you cannot yet imagine.','Where in your life do you need to trust the timing rather than forcing an outcome?','/cards/25-hourglass.png',NULL,'FREE',0,1,25,'2026-05-12 15:44:50.809','2026-05-14 12:14:32.235');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxgbc000q6sqoenaa4fne','cmp2sxe5v00006sqo1dppvi36','Exit','This key marks a threshold — a crossing point where one chapter closes and another begins. Something in your life is completing its cycle, inviting you to step through the doorway of change with grace and courage. The wisdom of knowing when to leave — to exit an old story, a harmful pattern, or a way of being that no longer serves you — is one of the most courageous acts on the spiritual path. Honor what was, release it with gratitude, and step forward into the new.','What is completing its cycle in your life, and what are you stepping toward?','/cards/26-exit.png',NULL,'FREE',0,1,26,'2026-05-12 15:44:50.904','2026-05-14 12:14:32.375');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxgec000r6sqocyl9z6a9','cmp2sxe5v00006sqo1dppvi36','Lady Beetle','Lady Beetle is the key of releasing old wounds that hold you back from your greatness. Like a can opener piercing solid steel, Lady Beetle breaks through the hardened shell around your heart, allowing long-trapped beliefs to finally spill out and be freed. Just as the snake sheds its skin, the leaves release from the trees, and birds molt their worn feathers, you too are entering a season of release. Allow this shedding — your long-held beliefs are asking to be let go so that something more truth-filled can take their place.','What old belief or pattern is ready to shed so something more true can take its place?','/cards/27-lady-beetle.png',NULL,'FREE',0,1,27,'2026-05-12 15:44:51.012','2026-05-14 12:14:32.515');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxgh4000s6sqo4ofse8qt','cmp2sxe5v00006sqo1dppvi36','Baseball Diamond','The Baseball Diamond is a powerful metaphor for the journey to wholeness — it illustrates the choices we face, encouraging us to step up to the plate and confront our issues. The Merkabah is our personal diamond-shaped electrical field that protects us, and it is up to us to keep it healthy and clear of incompatible energies. The Universe responds to our intentions rather than our mental requests — when you intend, for your self-betterment, that you need something to happen, it will be put into play. Know that in the bleachers of life, the whole Universe is cheering you on.','What decision or intention is ready to be put into play in your life?','/cards/28-baseball-diamond.png',NULL,'FREE',0,1,28,'2026-05-12 15:44:51.112','2026-05-14 12:14:32.654');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxgjy000t6sqovhkxara3','cmp2sxe5v00006sqo1dppvi36','Unity','When the mind, body, and spirit come into alignment, our soul evolves and we become whole — our thoughts calm, our bodies feel grounded, our souls expand. This inner harmony makes us more patient, kind, and aware of how our actions affect the world around us. As more individuals integrate their incoherent parts, humanity shifts from fear and fragmentation toward cooperation, empathy, and clarity of purpose. Heal yourself, and you heal those close to you — and then they heal and influence others, until the whole community is healed.','In what area of your life do you feel the most alignment between your thoughts, body, and spirit?','/cards/29-unity.png',NULL,'FREE',0,1,29,'2026-05-12 15:44:51.214','2026-05-14 12:14:32.799');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxgmp000u6sqolox4jw4t','cmp2sxe5v00006sqo1dppvi36','Gods Eye II','There are moments when the Divine falls completely silent, and this silence is the test: what do you do when the training wheels are removed? These moments aren\'t evidence of abandonment — they are evidence that you\'re ready for a deeper kind of relationship with your creator, built not on constant reassurance but on the quiet, steady courage of trust. The more you experience that you can move through fear and stay connected to your integrity even in silence, the more trust naturally grows. God may feel empty at times, but you are deservedly full — full of the strength, insight, and resilience you\'ve cultivated through every stage of your life.','What would it mean to trust your own inner anchor without waiting for an external sign?','/cards/30-gods-eye-ii.png',NULL,'FREE',0,1,30,'2026-05-12 15:44:51.313','2026-05-14 12:14:32.943');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxgpl000v6sqomj8w11qk','cmp2sxe5v00006sqo1dppvi36','Openness','Openness is the key that helps balance serving others with serving self. Empaths have a habit of putting others\' needs in front of their own and neglecting their mental, emotional, and physical health — your job is to be an inspiration, not to heal everyone without permission. Source weighs our works, not counts them, and people who do not truly love themselves are unable to offer unconditional love to others. If you are comfortable in your own skin, others will feel comfortable around you and ask you for help rather than you going all in without permission.','Where do you need to serve yourself first in order to truly serve others?','/cards/31-openness.png',NULL,'FREE',0,1,31,'2026-05-12 15:44:51.417','2026-05-14 12:14:33.084');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxgsb000w6sqop6f2iyxy','cmp2sxe5v00006sqo1dppvi36','Goddess Eye Full','Goddess Eye Full is the key of the 2nd chakra — the feminine center of deep empathy, emotional intuition, and receptivity. When this chakra falls out of balance, it can create the illusion of victimhood, as if others are judging or diminishing your worth — but this feeling is an energetic distortion, not reality. You are an eternal, sovereign being, and nothing can take your power unless you put out the welcome mat for it to enter. Find time in nature, sink your hands and feet into the Earth, and remember: if you want to be respected, you must respect yourself first.','What creative act could reconnect you to your sense of worth and feminine power?','/cards/32-goddess-eye-full.png',NULL,'FREE',0,1,32,'2026-05-12 15:44:51.515','2026-05-14 12:14:33.224');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxgv7000x6sqof20tl2wx','cmp2sxe5v00006sqo1dppvi36','God Going Out','God Going Out points to a shift away from old patterns of control, hierarchy, and externalized authority — what many would call the overactive masculine. When things in life stop working, it often reflects an inner system running on outdated beliefs: pushing over listening, striving over feeling, certainty over flow. This transition isn\'t about rejecting the masculine, but about integrating it with a more soul-based, receptive way of being. When the old \'god\' steps out, it\'s because a deeper inner guidance is ready to step in.','What outdated inner authority are you releasing to make room for a more soulful way of being?','/cards/33-god-going-out.png',NULL,'FREE',0,1,33,'2026-05-12 15:44:51.619','2026-05-14 12:14:33.369');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxgxv000y6sqoui8pu1y5','cmp2sxe5v00006sqo1dppvi36','Goddess Coming In','Goddess Coming In is the key of receptivity — an invitation to trust the unknown, the invisible, and the subtle inner voice that speaks beneath the noise. The Goddess is Mother Nature herself; through her, you release all burdens and are returned to the Father for rebirth. This is the time for the reconnection of masculine and feminine, heaven and Earth, electricity and magnetism — spirit into the physical in equality. When you allow her wisdom, you allow life to open in ways you once thought impossible, because we were all made to believe we didn\'t deserve it — and that time is now over.','What are you being invited to receive that you have been too guarded to accept?','/cards/34-goddess-coming-in.png',NULL,'FREE',0,1,34,'2026-05-12 15:44:51.715','2026-05-14 12:14:33.511');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxh0o000z6sqoco0bg865','cmp2sxe5v00006sqo1dppvi36','Female','This is the key of deliberately blocking out the masculine energy, or the physical world. The act of pausing, disconnecting from the external, and truly listening is critical when the time comes to sit in the silent grace of the Great Void. The divine feminine is always with you, holding you, grounding you, and awaiting your recognition — when she signals that it is time to connect, it is often because she has an important message to deliver. If we do not take breaks and reconnect, gentle nudges may intensify into forceful shoves, so honor her invitation and make time to listen.','What is the quiet inner voice of the feminine trying to tell you right now?','/cards/35-female.png',NULL,'FREE',0,1,35,'2026-05-12 15:44:51.816','2026-05-14 12:14:33.658');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxh3h00106sqo6snn8yi7','cmp2sxe5v00006sqo1dppvi36','Scarab','Once you\'ve named the toxins within — old beliefs, worn-out behaviors, and the residue of past emotions — the next step is to let them go. This inner cleansing mirrors the sacred work of the scarab, who gathers what is decayed and repurposes it into something new and useful. Collect the remnants of who you once were, honor them for what they taught you, and roll them gently from your path — what was once heavy becomes rich compost to feed new life. Care for your inner garden with patience and devotion, and your harvest will bloom in perfect reflection of your efforts.','What from your past can you honor, release, and compost into fuel for new growth?','/cards/36-scarab.png',NULL,'FREE',0,1,36,'2026-05-12 15:44:51.917','2026-05-14 12:14:33.814');
INSERT IGNORE INTO `Card` (`id`, `deckId`, `title`, `message`, `prompt`, `imageUrl`, `iconKey`, `accessType`, `guestPreview`, `isActive`, `sortOrder`, `createdAt`, `updatedAt`) VALUES ('cmp2sxh6h00116sqoj4d2pc6j','cmp2sxe5v00006sqo1dppvi36','Block','Block is a key of pure energetic boundary holding — a firm declaration that negative influences can no longer enter your space. Imagine extending your hand outward, halting anything or anyone that seeks to drain, disrupt, or diminish you — this gesture does not need to be physical, your imagination is the conduit. You are the sovereign solid black diamond in the center, surrounded by the square of stability and the circle of wholeness, harmony, and completion. With this key, you reclaim authority over your energy, your peace, and your sovereignty.','What boundary do you need to energetically declare to protect your peace and sovereignty?','/cards/37-block.png',NULL,'FREE',0,1,37,'2026-05-12 15:44:52.025','2026-05-14 12:14:33.968');
